import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"ATLAS Automation Exporter / Editor","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/atlas-plugins/automation-extractor.md","filePath":"en/projects/atlas-plugins/automation-extractor.md","lastUpdated":1793127012000}'),r={name:"en/projects/atlas-plugins/automation-extractor.md"};function n(s,e,l,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="atlas-automation-exporter-editor" tabindex="-1">ATLAS Automation Exporter / Editor <a class="header-anchor" href="#atlas-automation-exporter-editor" aria-label="Permalink to &quot;ATLAS Automation Exporter / Editor&quot;">​</a></h1><p>ATLAS Automation Exporter / Editor is an independently maintained external ATLAS plugin. The idea comes from the existing Windows tool for splitting <code>automations.yaml</code>, but moves directly into the ATLAS plugin architecture.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>The plugin analyzes Home Assistant automations safely, exports selected entries and prepares further editing through File Studio.</p><h2 id="repository" tabindex="-1">Repository <a class="header-anchor" href="#repository" aria-label="Permalink to &quot;Repository&quot;">​</a></h2><ul><li>GitHub: <code>https://github.com/rockbaer2007/atlas-automation-exporter-editor-plugin</code></li><li>Install page: <code>https://rockbaer2007.github.io/atlas-automation-exporter-editor-plugin/install.html</code></li><li>Repository file: <code>https://raw.githubusercontent.com/rockbaer2007/atlas-automation-exporter-editor-plugin/main/repository.json</code></li><li>current installable plugin version: <code>0.1.28</code></li><li>User interface in German, English and French; the saved ATLAS language is applied when the plugin opens.</li></ul><p>ATLAS Administration accepts the GitHub URL directly. During preview, ATLAS converts it to the matching <code>repository.json</code> address automatically.</p><p>Since 0.1.28, analysis counts actual YAML trigger, condition and action entries. Section headers and nested steps do not add root entries. Modern and classic syntax are supported. Settings and source automations are unchanged; reading the system file still creates a safety backup before analysis.</p><ul><li>read <code>/config/automations.yaml</code> through the approved File Studio path</li><li>create a safety backup before analyzing the loaded <code>/config/automations.yaml</code>, stored as <code>/config/atlas_backups/automations/&lt;date-time&gt;/automations.yaml</code></li><li>analyze external <code>.yaml</code> and <code>.yml</code> uploads</li><li>show id, alias, description, triggers, conditions and actions</li><li>detect service calls from classic <code>service:</code> and modern <code>action: domain.service</code> syntax</li><li>keep single automations with root-level trigger or action fragments as one entry instead of creating false duplicate conflicts</li><li>keep time triggers as quoted <code>HH:MM:SS</code> values during export and repair numeric second values such as <code>25200</code> back to <code>&#39;07:00:00&#39;</code></li><li>show analysis hints for missing or duplicate ids/aliases, missing triggers or actions and disabled automations</li><li>pre-mark duplicate ids and aliases directly in the automation list as conflicts</li><li>show duplicate ids and aliases as conflicts separate from general hints</li><li>filter to automations with hints only</li><li>show detail YAML with File Studio-like highlighting</li><li>limit the automation list to roughly 15 visible entries and keep it internally scrollable</li><li>surface related entities, scripts, scenes, helpers and notification targets</li><li>group and filter the automation list by domain, area or device</li><li>configure an export folder target</li><li>export selected automations into one timestamped run folder</li><li>create two files with the same automation filename: <code>export-version</code> with <code>id</code> and <code>bereinigte-import-version</code> without <code>id</code> for the Home Assistant YAML editor</li><li>show an overview of exported automations</li><li>prepare editing exported files through File Studio</li></ul><h2 id="safety-line" tabindex="-1">Safety Line <a class="header-anchor" href="#safety-line" aria-label="Permalink to &quot;Safety Line&quot;">​</a></h2><p>The plugin does not write back into Home Assistant system files. It reads system YAML or uploaded YAML files, creates a safety backup when opening the real <code>automations.yaml</code>, analyzes the automations and exports separate YAML files. Manual restore and further editing should continue through File Studio and Home Assistant&#39;s own YAML tools.</p><h2 id="safe-plugin-recovery" tabindex="-1">Safe plugin recovery <a class="header-anchor" href="#safe-plugin-recovery" aria-label="Permalink to &quot;Safe plugin recovery&quot;">​</a></h2><p>In <strong>Administration → Plugin Manager → Automation Exporter / Editor → Restore</strong>, select an existing backup. Review version, direction and compatibility, then use the action that backs up the current plugin and applies the selected version. Cancel leaves the installation unchanged. A concurrent change to plugin or management state requires a fresh preview.</p><p>This restores the <strong>plugin package</strong>. It does not roll source automations, exports, editor projects, trash or history back to earlier data. It neither imports into Home Assistant automatically nor writes back to <code>automations.yaml</code>.</p><div class="info custom-block"><p class="custom-block-title">Isolated qualification on 2026-10-16</p><p>Actual packages <strong>0.1.27 → 0.1.28 → 0.1.27 → 0.1.28</strong> passed on ATLAS 0.1.312, including restart, UI preview, cancellation and recovery. A stale preview was rejected after a real management change. Repository bundles and a complete isolated fixture archive were retained before changes. Source YAML, existing exports, project, another plugin, trash and history remained exact. DE/EN/FR analysis, byte-identical safety backups, export/import pairs with/without ID and opening exports in File Studio passed. HA version metadata came from a local test endpoint; this does not qualify real HA authentication, GitHub updates or data-format migration. <strong>Pi 5 and Proxmox were unchanged during this isolated check.</strong></p></div><div class="info custom-block"><p class="custom-block-title">Subsequent Pi 5 and Proxmox qualification on 2026-10-16</p><p>After fresh local HA backups and additional PC copies, both hosts passed <strong>installed 0.1.28 → 0.1.27 → original 0.1.28</strong>. The actual older package was applied through the backend compatibility preview; cancellation and recovery from the new backup used Administration. Both retain ATLAS 0.1.312 and HA 2026.10.1.</p><p>All nine original plugin assets were restored exactly. Checked source automations, existing exports and automation backups, settings, server projects, other plugins, trash and history were preserved. Analysis of an uploaded synthetic YAML fixture was identical before and after recovery. No user automation was exported, executed or written back to HA; no HA/App restart was needed. This does not qualify a complete HA restore, data-format migration or a new GitHub release.</p></div><p>Reload Administration and the plugin page after recovery. During testing, the open Administration briefly reported unsaved shared changes although server recovery was correct. Reloading showed the shared server state again. Do not adopt an old local state solely because of that message.</p><p>Language and appearance are stored locally. Loaded analysis, selection, filters, the entered export folder and export overview belong to the current session. After reloading, load the source again and select the target folder if needed. Previously saved export files remain available in File Studio.</p><h2 id="positioning" tabindex="-1">Positioning <a class="header-anchor" href="#positioning" aria-label="Permalink to &quot;Positioning&quot;">​</a></h2><p>ATLAS Automation Exporter / Editor complements File Studio: File Studio is the safe file surface, while Automation Exporter / Editor is the domain-specific analysis and export surface for automations.</p>',20)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
